Definition lsh_hash_safe (n num_tables : i64) (vec : list f32) (seed : u64) : list u64 :=
  let num_tables_safe := Z.max 0 num_tables in
  List.map (fun table_idx =>
    let table_seed := (seed + u64_from_i64 table_idx)%Z in
    let proj := reduce_f32 Rplus 0%R (map2 (fun v i =>
      let pseudo_u64 := ((table_seed + u64_from_i64 i) * 2654435761)%Z in
      let pseudo_norm := ((f32_from_i64 (i64_from_u64 (pseudo_u64 mod 10000)) / 5000) - 1)%R in
      (v * pseudo_norm)%R
    ) vec (iota n)) in
    let norm := f32_sqrt (reduce_f32 Rplus 0%R (map_f32 (fun v => (v * v)%R) vec)) in
    let proj_normalized := if Rgt_dec norm 0%R then (proj / norm)%R else proj in
    if Rgt_dec proj_normalized 0%R then 1%Z else 0%Z
  ) (iota num_tables_safe).

Theorem lsh_hash_length : forall n num_tables vec seed,
  (num_tables >= 0)%Z ->
  length (lsh_hash_safe n num_tables vec seed) = Z.to_nat num_tables.
Proof.
  intros. unfold lsh_hash_safe.
  remember (Z.max 0 num_tables) as num_tables_safe.
  admit.
Admitted.

Definition conv1d_safe (input_len kernel_size : i64) (input kernel : list f32) : list f32 :=
  if orb (kernel_size <=? 0)%Z (kernel_size >? input_len)%Z then []
  else
    let out_len := (input_len - kernel_size + 1)%Z in
    List.map (fun i =>
      reduce_f32 Rplus 0%R (map2_f32 Rmult (firstn (Z.to_nat kernel_size) (skipn (Z.to_nat i) input)) kernel)
    ) (iota out_len).

Definition maxpool1d_safe (input_len pool_size : i64) (input : list f32) : list f32 :=
  if (pool_size <=? 0)%Z then []
  else
    let num_pools := (input_len / pool_size)%Z in
    List.map (fun i =>
      let pool_start := (i * pool_size)%Z in
      let pool_end := Z.min (pool_start + pool_size) input_len in
      reduce_f32 f32_max (-f32_inf) (firstn (Z.to_nat (pool_end - pool_start)) (skipn (Z.to_nat pool_start) input))
    ) (iota num_pools).

Definition elem_add_safe (n : i64) (a b : list f32) : list f32 := map2_f32 Rplus a b.
Definition elem_mul_safe (n : i64) (a b : list f32) : list f32 := map2_f32 Rmult a b.
Definition elem_div_safe (n : i64) (a b : list f32) : list f32 := map2_f32 (fun x y => if Req_dec y 0%R then 0%R else (x / y)%R) a b.
Definition elem_sub_safe (n : i64) (a b : list f32) : list f32 := map2_f32 Rminus a b.

Definition scalar_add_safe (n : i64) (a : list f32) (s : f32) : list f32 := map_f32 (fun x => (x + s)%R) a.
Definition scalar_mul_safe (n : i64) (a : list f32) (s : f32) : list f32 := map_f32 (fun x => (x * s)%R) a.
Definition scalar_div_safe (n : i64) (a : list f32) (s : f32) : list f32 :=
  if Req_dec s 0%R then replicate_f32 (Z.to_nat n) 0%R else map_f32 (fun x => (x / s)%R) a.

Definition sum_safe (n : i64) (x : list f32) : f32 := reduce_f32 Rplus 0%R x.
Definition mean_safe (n : i64) (x : list f32) : f32 :=
  if (n =? 0)%Z then 0%R else (reduce_f32 Rplus 0%R x / f32_from_i64 n)%R.
Definition max_safe (n : i64) (x : list f32) : f32 :=
  if (n =? 0)%Z then f32_nan else reduce_f32 f32_max (-f32_inf) x.
Definition min_safe (n : i64) (x : list f32) : f32 :=
  if (n =? 0)%Z then f32_nan else reduce_f32 f32_min f32_inf x.

Record complex : Type := mk_complex {
  re : f32;
  im : f32
}.

Definition complex_add (a b : complex) : complex :=
  mk_complex (re a + re b)%R (im a + im b)%R.

Definition complex_sub (a b : complex) : complex :=
  mk_complex (re a - re b)%R (im a - im b)%R.

Definition complex_mul (a b : complex) : complex :=
  mk_complex (re a * re b - im a * im b)%R (re a * im b + im a * re b)%R.

Definition complex_conj (a : complex) : complex :=
  mk_complex (re a) (-im a)%R.

Definition complex_abs (a : complex) : f32 :=
  let re_sq := (re a * re a)%R in
  let im_sq := (im a * im a)%R in
  let sum := (re_sq + im_sq)%R in
  if Rgt_dec sum 1e30%R then
    let scale := f32_max (f32_abs (re a)) (f32_abs (im a)) in
    let re_norm := (re a / scale)%R in
    let im_norm := (im a / scale)%R in
    (scale * f32_sqrt (re_norm * re_norm + im_norm * im_norm))%R
  else f32_sqrt sum.

Definition complex_abs_sq (a : complex) : f32 :=
  let re_sq := (re a * re a)%R in
  let im_sq := (im a * im a)%R in
  if orb (Rgt_dec re_sq 1e30%R) (Rgt_dec im_sq 1e30%R) then 1e30%R
  else (re_sq + im_sq)%R.

Definition complex_scale (s : f32) (a : complex) : complex :=
  mk_complex (s * re a)%R (s * im a)%R.

Definition complex_from_polar (r theta : f32) : complex :=
  let theta_mod := (theta - f32_from_i64 (i64_from_f32 (theta / (2 * f32_pi))) * (2 * f32_pi))%R in
  mk_complex (r * f32_cos theta_mod)%R (r * f32_sin theta_mod)%R.

Definition complex_normalize (a : complex) : complex :=
  let mag := complex_abs a in
  if Req_dec mag 0%R then mk_complex 0%R 0%R
  else complex_scale (1 / mag)%R a.

Definition rgpu_edge_quality_to_weight (quality : i32) : f32 :=
  if (quality =? 0)%Z then 0.25%R
  else if (quality =? 1)%Z then 1.0%R
  else if (quality =? 2)%Z then 0.75%R
  else if (quality =? 3)%Z then 0.1%R
  else if (quality =? 4)%Z then 0.5%R
  else 0.0%R.

Axiom reduce_by_index : forall A, list A -> (A -> A -> A) -> A -> list i64 -> list A -> list A.

Definition rgpu_compute_degree_sequence (num_nodes num_edges : i64) (edge_sources edge_targets : list i64) : (list i64 * list i64) :=
  let out_degrees := reduce_by_index i64 (replicate_f32 (Z.to_nat num_nodes) 0%Z) Z.add 0%Z edge_sources (replicate_f32 (Z.to_nat num_edges) 1%Z) in
  let in_degrees := reduce_by_index i64 (replicate_f32 (Z.to_nat num_nodes) 0%Z) Z.add 0%Z edge_targets (replicate_f32 (Z.to_nat num_edges) 1%Z) in
  (out_degrees, in_degrees).

Definition rgpu_canonical_form_signature (num_nodes num_edges : i64) (edge_sources edge_targets : list i64) (edge_qualities : list i32) : u64 :=
  let '(out_degrees, in_degrees) := rgpu_compute_degree_sequence num_nodes num_edges edge_sources edge_targets in
  let degree_hash := fold_left (fun h d => (h * 31 + u64_from_i64 d)%Z) out_degrees 0%Z in
  let in_degree_hash := fold_left (fun h d => (h * 37 + u64_from_i64 d)%Z) in_degrees 0%Z in
  let quality_hash := fold_left (fun h q => (h * 41 + u64_from_i64 (i64_from_i32 q))%Z) edge_qualities 0%Z in
  let node_count_hash := (u64_from_i64 num_nodes * 1000003)%Z in
  let edge_count_hash := (u64_from_i64 num_edges * 999983)%Z in
  Z.lxor (Z.lxor (Z.lxor degree_hash in_degree_hash) quality_hash) (Z.lxor node_count_hash edge_count_hash).

Axiom radix_sort : forall (num_bits : nat) (get_bit : u64 -> nat -> bool) (boxes : list u64), list u64.

Definition rgpu_update_edge_weights (n : i64) (current_weights feedback : list f32) (learning_rate : f32) : list f32 :=
  map2_f32 (fun w f =>
    let f_safe := if orb (f32_isnan f) (f32_isinf f) then 0%R else f32_max (-1%R) (f32_min 1%R f) in
    let delta := (learning_rate * f_safe)%R in
    let new_weight := (w + delta)%R in
    f32_max 0%R (f32_min 1%R new_weight)
  ) current_weights feedback.

Definition rgpu_adaptive_weight (n : i64) (base_weights temporal_factors spatial_factors semantic_factors : list f32) : list f32 :=
  List.map (fun '(base, (temp, (spat, sem))) =>
    let temp_safe := f32_max 0%R (f32_min 2%R temp) in
    let spat_safe := f32_max 0%R (f32_min 2%R spat) in
    let sem_safe := f32_max 0%R (f32_min 2%R sem) in
    let adaptive := (base * temp_safe * spat_safe * sem_safe)%R in
    f32_max 0%R (f32_min 1%R adaptive)
  ) (combine base_weights (combine temporal_factors (combine spatial_factors semantic_factors))).

Axiom f32_pow : f32 -> f32 -> f32.

Definition rgpu_xy_route (src_x src_y dst_x dst_y grid_width : i64) : (i64 * list i64) :=
  if (grid_width <=? 0)%Z then (0%Z, [])
  else
    let dx := Z.abs (dst_x - src_x) in
    let dy := Z.abs (dst_y - src_y) in
    let total_hops := (dx + dy)%Z in
    let path_x_dir := if (dst_x >? src_x)%Z then 1%Z else if (dst_x <? src_x)%Z then (-1)%Z else 0%Z in
    let path_y_dir := if (dst_y >? src_y)%Z then 1%Z else if (dst_y <? src_y)%Z then (-1)%Z else 0%Z in
    let x_steps := List.map (fun i =>
      let current_x := (src_x + (i + 1) * path_x_dir)%Z in
      let current_y := src_y in
      Z.max 0 (current_y * grid_width + current_x)%Z
    ) (iota dx) in
    let y_steps := List.map (fun i =>
      let current_y := (src_y + (i + 1) * path_y_dir)%Z in
      let current_x := dst_x in
      Z.max 0 (current_y * grid_width + current_x)%Z
    ) (iota dy) in
    (total_hops, x_steps ++ y_steps).

Definition rgpu_route_cost (src_x src_y dst_x dst_y : i64) (hop_cost congestion_factor : f32) : f32 :=
  let dx := f32_from_i64 (Z.abs (dst_x - src_x)) in
  let dy := f32_from_i64 (Z.abs (dst_y - src_y)) in
  let base_cost := ((dx + dy) * hop_cost)%R in
  let manhattan_distance := (dx + dy)%R in
  let congestion_penalty := if Rgt_dec manhattan_distance 100%R then (congestion_factor * 10000)%R else (congestion_factor * manhattan_distance * manhattan_distance)%R in
  f32_min 1e10%R (base_cost + congestion_penalty)%R.

Definition rgpu_balance_load (num_cores : i64) (core_loads : list f32) : list f32 :=
  if (num_cores =? 0)%Z then []
  else
    let total_load := reduce_f32 Rplus 0%R core_loads in
    let avg_load := (total_load / f32_from_i64 num_cores)%R in
    let max_deviation := (0.1 * avg_load)%R in
    let upper := (avg_load + max_deviation)%R in
    let lower := (avg_load - max_deviation)%R in
    map_f32 (fun load => f32_max lower (f32_min upper load)) core_loads.

Definition rgpu_compute_sparsity_ratio (n : i64) (workloads : list f32) (threshold : f32) : f32 :=
  if (n =? 0)%Z then 0%R
  else
    let mask := map_f32 (fun w => if Rge_dec w threshold then 1%R else 0%R) workloads in
    let inactive_count := reduce_f32 Rplus 0%R (map_f32 (fun m => if Req_dec m 1%R then 0%R else 1%R) mask) in
    (inactive_count / f32_from_i64 n)%R.

Definition rgpu_quantum_correlation (state1 state2 : complex) : complex :=
  complex_mul state1 (complex_conj state2).

Definition rgpu_entangle_states (state1 state2 : complex) : complex :=
  let sum_state := complex_add state1 state2 in
  let sqrt_2_inv := (1 / f32_sqrt 2)%R in
  complex_scale sqrt_2_inv sum_state.

Definition rgpu_measure_probability (state : complex) : f32 :=
  let abs_sq := complex_abs_sq state in
  f32_min 1%R (f32_max 0%R abs_sq).

Definition rgpu_hadamard_transform (state : complex) : complex :=
  let sqrt_2_inv := (1 / f32_sqrt 2)%R in
  let re_new := ((re state + im state) * sqrt_2_inv)%R in
  let im_new := ((re state - im state) * sqrt_2_inv)%R in
  complex_normalize (mk_complex re_new im_new).

Definition rgpu_phase_shift (state : complex) (theta : f32) : complex :=
  let rotation := complex_from_polar 1%R theta in
  complex_mul state rotation.

Definition rgpu_pauli_x (state : complex) : complex :=
  mk_complex (im state) (re state).

Definition rgpu_pauli_y (state : complex) : complex :=
  let i_times_state := mk_complex (-im state)%R (re state) in
  i_times_state.

Definition rgpu_pauli_z (state : complex) : complex :=
  mk_complex (re state) (-im state)%R.

Definition rgpu_cnot (control target : complex) : (complex * complex) :=
  let should_flip := Rgt_dec (complex_abs control) 0.5%R in
  let new_target := if should_flip then rgpu_pauli_x target else target in
  (control, new_target).

Definition rgpu_fractal_transform (state : complex) (depth : i64) : complex :=
  let depth_safe := Z.max 0 depth in
  let fix transform_step (s : complex) (i : i64) {struct i} : complex :=
    match i with
    | Z0 => s
    | Zpos _ =>
      let scale_factor := (1 / f32_pow 2%R (f32_from_i64 i))%R in
      let phase := f32_atan2 (im s) (re s) in
      let rotation := complex_from_polar scale_factor (phase * scale_factor)%R in
      let sum_state := complex_add s rotation in
      let norm_factor := (1 / f32_sqrt (1 + scale_factor * scale_factor))%R in
      transform_step (complex_scale norm_factor sum_state) (i - 1)
    | Zneg _ => s
    end
  in transform_step state depth_safe.

Definition rgpu_relational_and (state1 state2 : complex) : complex :=
  complex_normalize (complex_mul state1 state2).

Definition rgpu_relational_or (state1 state2 : complex) : complex :=
  let sqrt_2_inv := (1 / f32_sqrt 2)%R in
  let sum_state := complex_add state1 state2 in
  complex_normalize (complex_scale sqrt_2_inv sum_state).

Definition rgpu_relational_xor (state1 state2 : complex) : complex :=
  let sqrt_2_inv := (1 / f32_sqrt 2)%R in
  let diff_state := complex_sub state1 state2 in
  complex_normalize (complex_scale sqrt_2_inv diff_state).

Definition rgpu_partition_nodes (num_nodes num_cores : i64) : list i64 :=
  if (num_cores <=? 0)%Z then replicate_f32 (Z.to_nat num_nodes) 0%Z
  else
    let nodes_per_core := (num_nodes / num_cores)%Z in
    let remainder := (num_nodes mod num_cores)%Z in
    List.map (fun i =>
      if (i <? remainder * (nodes_per_core + 1))%Z then
        (i / (nodes_per_core + 1))%Z
      else
        (remainder + (i - remainder * (nodes_per_core + 1)) / nodes_per_core)%Z
    ) (iota num_nodes).

Definition rgpu_compute_partition_boundaries (num_nodes num_cores : i64) : list i64 :=
  let num_cores_safe := Z.max 1 num_cores in
  let nodes_per_core := (num_nodes / num_cores_safe)%Z in
  let remainder := (num_nodes mod num_cores_safe)%Z in
  List.map (fun i =>
    if (i =? 0)%Z then 0%Z
    else if (i <=? remainder)%Z then (i * (nodes_per_core + 1))%Z
    else (remainder * (nodes_per_core + 1) + (i - remainder) * nodes_per_core)%Z
  ) (iota (num_cores_safe + 1)).

Definition rgpu_noc_neighbors (core_id grid_width grid_height : i64) : list i64 :=
  if orb (grid_width <=? 0)%Z (grid_height <=? 0)%Z then [(-1)%Z; (-1)%Z; (-1)%Z; (-1)%Z]
  else
    let x := (core_id mod grid_width)%Z in
    let y := (core_id / grid_width)%Z in
    let left := if (x >? 0)%Z then (core_id - 1)%Z else (-1)%Z in
    let right := if (x <? grid_width - 1)%Z then (core_id + 1)%Z else (-1)%Z in
    let up := if (y >? 0)%Z then (core_id - grid_width)%Z else (-1)%Z in
    let down := if (y <? grid_height - 1)%Z then (core_id + grid_width)%Z else (-1)%Z in
    [left; right; up; down].

Definition rgpu_compute_core_position (core_id grid_width : i64) : (i64 * i64) :=
  if (grid_width <=? 0)%Z then (0%Z, 0%Z)
  else ((core_id mod grid_width)%Z, (core_id / grid_width)%Z).

Definition rgpu_core_id_from_position (x y grid_width : i64) : i64 :=
  if (grid_width <=? 0)%Z then 0%Z else (y * grid_width + x)%Z.

Definition rgpu_manhattan_distance (src_core dst_core grid_width : i64) : i64 :=
  if (grid_width <=? 0)%Z then 0%Z
  else
    let '(src_x, src_y) := rgpu_compute_core_position src_core grid_width in
    let '(dst_x, dst_y) := rgpu_compute_core_position dst_core grid_width in
    Z.abs (dst_x - src_x) + Z.abs (dst_y - src_y).

Definition rgpu_message_latency (src_core dst_core grid_width : i64) (hop_latency base_latency : f32) : f32 :=
  let hops := rgpu_manhattan_distance src_core dst_core grid_width in
  let hop_contrib := f32_min 1e6%R (f32_from_i64 hops * hop_latency)%R in
  (base_latency + hop_contrib)%R.

